// errNoRepoAvailable is returned when at least one cell answered but none
// matched the repo filter. A typo'd name or missing access cannot reach this
// point — resolveScope already validated the slug against the control-plane
// repo index — so the message names only the causes that survive: query-serve
// hasn't indexed the repo, or its owner org isn't enabled for semantic search.
var errNoRepoAvailable = errors.New("semantic search cannot search this repo yet — it may not be indexed, or semantic search may not be enabled for its owner")

// errNoRegionAvailable is returned when every queried cell lacks query-serve.
var errNoRegionAvailable = errors.New("semantic search is not yet available in the region(s) hosting this search")

// tier0Row pairs a tier-0 result with its rank within the cell that returned
// it — the selection order the mixed-capability fallback preserves (see
// sortTier0Rows).
type tier0Row struct {
	r        search.Result
	cellRank int
}

// rankSemanticResults buckets every page's rows and applies the SAME ordering
// the BFF's cross-cell merge uses (see the ordering contract on
// mergeSemanticV4Responses): repos first by retrieval score desc, then tier 0
// (sortTier0Rows), then tier 1 by rerank desc with retrieval Score tiebreak.
// Every other non-repo row — tier 2 (the retired ANN-only fallback, still
// emitted by un-redeployed cells) and rows with no tier at all — is DROPPED,
// exactly as the BFF drops them. Ordering by rerank score — not BM25 or the
// per-namespace retrieval Score — is what keeps the CLI in parity with the
// web: query-serve documents that Score "is not the field results are ordered
// by … sorting by it undoes reranking."
func rankSemanticResults(pages []semanticCellPage) (merged []search.Result) {
	var repos, tier1 []search.Result
	var tier0 []tier0Row
	for _, p := range pages {
		cellRank := 0
		for _, r := range p.body.Results {
			switch {
			case r.Type == search.TypeRepo:
				repos = append(repos, r)
			case tierOf(r) == 0:
				tier0 = append(tier0, tier0Row{r: r, cellRank: cellRank})
				cellRank++
			case tierOf(r) == 1:
				tier1 = append(tier1, r)
			}
		}
	}
	sort.SliceStable(repos, func(i, j int) bool { return repos[i].Meta.Score > repos[j].Meta.Score })
	merged = append(merged, repos...)
	sortTier0Rows(tier0)
	// Tier 1: rerank score decides, retrieval Score breaks ties. Rows whose
	// cell fell back (no rerank score) sort last, matching the BFF.
	sort.SliceStable(tier1, func(i, j int) bool {
		if ri, rj := rerankOf(tier1[i]), rerankOf(tier1[j]); ri != rj {
			return ri > rj
		}
		return tier1[i].Meta.Score > tier1[j].Meta.Score
	})

func AppendUnique(existing []string, values ...string) []string {
	if len(values) == 0 {
		return existing
	}

	seen := make(map[string]struct{}, len(existing)+len(values))
	for _, value := range existing {
		seen[value] = struct{}{}
	}
	for _, value := range values {
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		existing = append(existing, value)
	}

	return existing
}

// CellV4 performs a v4 query-serve search against a single entire-api
// cell, via the pre-authenticated client (bearer = jurisdictional identity
// token; host = the cell). repoIDs are repo ULIDs to scope to (the v4 route is
// per-repo and keys on ULIDs, not owner/name slugs); an empty repoIDs means
// "every repo the caller can access in this cell" — query-serve fans out across
// those namespaces itself. The cross-cell fan-out and merge live in the cli
// layer (mirroring code search), so this is the single-cell primitive it calls.
func CellV4(ctx context.Context, client *api.Client, cfg Config, repoIDs []string) (*Response, error) {
	ctx, cancel := context.WithTimeout(ctx, apiTimeout)
	defer cancel()

	q := url.Values{}
	q.Set("q", cfg.Query)
	filtered := false
	for _, id := range repoIDs {
		if id != "" {
			q.Add("repo", id)
			filtered = true
		}
	}
	addCommonSearchParams(q, cfg)

	resp, err := client.Get(ctx, v4ServicePath+"?"+q.Encode())
	if err != nil {
		return nil, fmt.Errorf("calling search service: %w", err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return nil, fmt.Errorf("reading response: %w", err)
	}
	if resp.StatusCode == http.StatusNotFound {
		// Two distinct 404s share this status. A JSON error body is
		// query-serve answering through the gateway: the route exists but the
		// repo filter matched nothing the caller may search (not indexed, or
		// the owner org isn't flag-enabled — entire-search fails closed,
		// existence not disclosed). A plain "404 page not found" is the
		// gateway itself: no semantic-search route, query-serve not deployed
		// in this cell. Deployed cells answer unfiltered searches of unknown
		// repos with an empty 200, so the split is unambiguous. The
		// repo-filter-miss reading only holds when a filter was actually sent
		// — an unfiltered call named no repo to blame, so its JSON 404
		// (whatever produced it) degrades to the ErrCellUnavailable fail-safe.
		var errResp struct {
			Error string `json:"error"`
		}
		if filtered && json.Unmarshal(body, &errResp) == nil && errResp.Error != "" {
			// Wrap rather than return the bare sentinel so the server's own
			// message survives into debug logs; errors.Is still matches.
			return nil, fmt.Errorf("%w: %s", ErrRepoFilterUnmatched, errResp.Error)
		}
		return nil, ErrCellUnavailable
	}
	return parseSearchResponse(resp.StatusCode, body)
}

// addCommonSearchParams sets the query params other than the repo scoping
// (repo IDs are added by CellV4's caller). types is deliberately never sent —
// the backend returns all types.
func addCommonSearchParams(q url.Values, cfg Config) {
	if cfg.Limit > 0 {
		q.Set("limit", strconv.Itoa(cfg.Limit))
	}
	if cfg.Author != "" {
		q.Set("author", cfg.Author)
	}
	if cfg.Date != "" {
		q.Set("date", cfg.Date)
	}
	if cfg.Branch != "" {
		q.Set("branch", cfg.Branch)
	}
	if cfg.Page > 0 {
		q.Set("page", strconv.Itoa(cfg.Page))
	}
}

// parseSearchResponse decodes a search response body, preserving the
// long-standing error wording so callers (and error-message assertions) are
// unchanged.
func parseSearchResponse(statusCode int, body []byte) (*Response, error) {
	if statusCode != http.StatusOK {
		var errResp struct {
			Error string `json:"error"`
		}
		if json.Unmarshal(body, &errResp) == nil && errResp.Error != "" {
			return nil, fmt.Errorf("search service error (%d): %s", statusCode, errResp.Error)
		}
		return nil, fmt.Errorf("search service returned %d: %s", statusCode, string(body))
	}

	var result Response
	if err := json.Unmarshal(body, &result); err != nil {
		return nil, fmt.Errorf("unexpected response from search service: %s", string(body))
	}

	if result.Error != "" {
		return nil, fmt.Errorf("search service error: %s", result.Error)
	}

	return &result, nil
}

