func (s *Server) loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		sw := &statusWriter{ResponseWriter: w, status: 200}
		next.ServeHTTP(sw, r)
		s.logger.Info().
			Str("method", r.Method).
			Str("path", r.URL.Path).
			Int("status", sw.status).
			Dur("duration", time.Since(start)).
			Msg("request")
	})
}

type statusWriter struct {
	http.ResponseWriter
	status int
}

func (sw *statusWriter) WriteHeader(code int) {
	sw.status = code
	sw.ResponseWriter.WriteHeader(code)
}

func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(map[string]interface{}{
		"status":    "ok",
		"service":   "entire-search-query",
		"timestamp": time.Now().UnixMilli(),
	})
}

func (s *Server) handleSearch(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()

	// Auth. Repo access is resolved per verified caller, so every request must resolve to a
	// verified user identity.
	authResult, err := resolveUserID(ctx, r, s.dbClient, s.jwksVerifier)
	if err != nil {
		s.logger.Warn().Err(err).Msg("auth failed")
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "Unauthorized"})
		return
	}

	// Authorized search requires a verified account id (JWT sub). The
	// ent_*/PAT auth paths don't carry one — reject rather than under-filter.
	if authResult.AccountID == "" {
		writeJSON(w, http.StatusForbidden, map[string]string{"error": "Forbidden"})
		return
	}

	// Parse query params.
	q := strings.TrimSpace(r.URL.Query().Get("q"))
	if q == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "Query parameter 'q' is required"})
		return
	}
	if len(q) > maxQueryLength {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "Query too long (max 500 characters)"})
		return
	}

	branch := r.URL.Query().Get("branch")
	if len(branch) > maxBranchLength {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "Branch name too long (max 250 characters)"})
		return
	}

	dateParam := r.URL.Query().Get("date")
	if dateParam != "" && dateParam != "week" && dateParam != "month" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "Invalid date value. Must be one of: week, month"})
		return
	}

	modeParam := r.URL.Query().Get("mode")
	mode := searcher.SearchMode("")
	if modeParam != "" {
		if modeParam != "hybrid" && modeParam != "keyword" {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "Invalid mode. Must be one of: hybrid, keyword"})
			return
		}
