const (
	defaultJWKSCacheTTL = 5 * time.Minute
	jwksFetchTimeout    = 10 * time.Second
	jwksFetchCooldown   = 30 * time.Second // min interval between fetches per issuer
)

// CoreClaims holds the parsed claims from an entire-core JWT.
type CoreClaims struct {
	josejwt.Claims
	Handle         string `json:"handle"`
	Provider       string `json:"provider"`
	ProviderUserID string `json:"provider_user_id"`
	Scope          string `json:"scope"`
}

// JWKSVerifier validates entire-core JWTs. JWT verification itself — issuer
// trust (before any JWKS fetch), JWKS fetch/cache/refresh/kid-lookup,
// signature verification, RFC 7519 time claims, and any-of audience matching
// — is entirely delegated to the shared
// github.com/entirehq/entiredb/modules/jwtverify module's TrustedIssuers.
// The one thing that stays entire-search's own business logic (not JWT
// verification) is the provider/provider_user_id check.
type JWKSVerifier struct {
	trustedIssuers *jwtverify.TrustedIssuers
}

// NewJWKSVerifier creates a verifier that accepts JWTs from the given trusted
// issuers and validates the audience claim against the given audiences.
func NewJWKSVerifier(trustedIssuers []string, audiences []string) *JWKSVerifier {
	return &JWKSVerifier{
		trustedIssuers: jwtverify.NewTrustedIssuers(
			trustedIssuers,
			defaultJWKSCacheTTL,
			jwtverify.WithAudiences(audiences),
			jwtverify.WithMinRefetchInterval(jwksFetchCooldown),
			jwtverify.WithHTTPClient(&http.Client{Timeout: jwksFetchTimeout}),
		),
	}
}

// Verify parses and validates a core JWT token string. Returns the parsed
// claims on success. jwtverify.TrustedIssuers handles issuer trust, JWKS
// fetch/cache/refresh, signature verification, RFC 7519 time claims
// (including requiring exp to be present), and audience matching (any-of,
// ENT-1050) — including enforcing HTTPS-only JWKS origins and safe
// redirects. entire-search only additionally requires the caller be a
// GitHub-identified account.
func (v *JWKSVerifier) Verify(ctx context.Context, tokenString string) (*CoreClaims, error) {
	claims := &CoreClaims{}
	if err := v.trustedIssuers.Verify(ctx, tokenString, claims); err != nil {
		return nil, fmt.Errorf("verifying token: %w", err)
	}

	if claims.Provider != "github" {
		return nil, fmt.Errorf("unsupported provider: %q", claims.Provider)
	}
	if claims.ProviderUserID == "" {
		return nil, fmt.Errorf("missing provider_user_id")
	}

	return claims, nil
}

