// (ENT-1551). The issuer is safe to dial: it is the verified iss claim, and
// verification rejects any issuer outside the configured trusted set. Empty
// issuer (legacy/test callers) falls back to the configured regional URL.
func (r *CoreReposV4RepoResolver) reposURLFor(issuer string) string {
	if issuer == "" {
